"""Regenerate data/demos.js from tools/demos.py.

Edit tools/demos.py, then run:  python tools/build_data.py
"""
import json
from pathlib import Path

from demos import COURSE_TITLE, CURRICULUM, DEMOS

out = Path(__file__).resolve().parent.parent / "data" / "demos.js"
data = {"course": COURSE_TITLE, "demos": DEMOS, "curriculum": CURRICULUM}
out.write_text(
    "// Generated by tools/build_data.py from tools/demos.py - edit that file, not this one.\n"
    "window.MBOT_DATA = " + json.dumps(data, ensure_ascii=False, indent=1) + ";\n",
    encoding="utf-8",
)
print("wrote", out)
